// Package licenses prints the project's license and the notices of the
// third-party modules linked into this build.
//
// The embed directory is generated by scripts/generate-licenses.go; do not
// edit it by hand.
package licenses

import (
	"bytes"
	"embed"
	"encoding/json"
	"fmt"
	"io"
	"runtime/debug"
)

// The catalog covers every release target, so one source tree cross-builds
// without regeneration. Build metadata selects this executable's modules.
//
//go:embed embed
var notices embed.FS

type module struct {
	Path  string
	SPDX  string
	Files []string
}

// Write prints the project NOTICE and LICENSE, then the full license and
// notice texts of each module linked into the running executable, then, for
// the Linux window build, the notice of the native libraries it links.
func Write(out io.Writer) error {
	info, ok := debug.ReadBuildInfo()
	if !ok {
		return fmt.Errorf("licenses: Go build information is unavailable")
	}
	return writeForBuild(out, info)
}

// writeForBuild takes the build information as an input, so tests can check
// the output for cross-built executables they cannot run.
func writeForBuild(out io.Writer, info *debug.BuildInfo) error {
	manifest, err := notices.ReadFile("embed/modules.json")
	if err != nil {
		return err
	}
	var entries []module
	if err := json.Unmarshal(manifest, &entries); err != nil {
		return err
	}
	known := make(map[string]bool, len(entries))
	for _, entry := range entries {
		known[entry.Path] = true
	}
	linked := make(map[string]bool, len(info.Deps))
	for _, dep := range info.Deps {
		if !known[dep.Path] {
			return fmt.Errorf("licenses: no embedded license for linked module %s", dep.Path)
		}
		linked[dep.Path] = true
	}
	if err := writeText(out, "NOTICE"); err != nil {
		return err
	}
	if _, err := fmt.Fprint(out, "\n--- LICENSE ---\n"); err != nil {
		return err
	}
	if err := writeText(out, "LICENSE"); err != nil {
		return err
	}
	for _, entry := range entries {
		if !linked[entry.Path] {
			continue
		}
		if _, err := fmt.Fprintf(out, "\nModule: %s\nSPDX: %s\n", entry.Path, entry.SPDX); err != nil {
			return err
		}
		for _, path := range entry.Files {
			if _, err := fmt.Fprintf(out, "\n--- %s ---\n", path); err != nil {
				return err
			}
			if err := writeText(out, path); err != nil {
				return err
			}
		}
	}
	// Module metadata lists no native libraries: a Linux cgo build that
	// links Wails links GTK and WebKitGTK.
	var goos, cgo string
	for _, setting := range info.Settings {
		switch setting.Key {
		case "GOOS":
			goos = setting.Value
		case "CGO_ENABLED":
			cgo = setting.Value
		}
	}
	if goos == "linux" && cgo == "1" && linked["github.com/wailsapp/wails/v3"] {
		return writeText(out, "native-linux/NOTICE")
	}
	return nil
}

func writeText(out io.Writer, path string) error {
	data, err := notices.ReadFile("embed/" + path)
	if err != nil {
		return err
	}
	if _, err := out.Write(data); err != nil {
		return err
	}
	if !bytes.HasSuffix(data, []byte("\n")) {
		_, err = fmt.Fprintln(out)
	}
	return err
}
